import { useState, useCallback, KeyboardEvent } from 'react';
import { JxInputField, JxChip } from '@jinx-ui/react';

interface ArticleTagInputProps {
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagInput({ defaultTags = [], onChange }: ArticleTagInputProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);
  const [draft, setDraft] = useState('');

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  const addTag = useCallback(() => {
    const value = draft.trim();
    if (!value || tags.includes(value)) {
      setDraft('');
      return;
    }
    commit([...tags, value]);
    setDraft('');
  }, [draft, tags, commit]);

  const removeTag = useCallback(
    (index: number) => {
      commit(tags.filter((_, i) => i !== index));
    },
    [tags, commit],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag();
    } else if (event.key === 'Backspace' && draft.length === 0 && tags.length > 0) {
      event.preventDefault();
      removeTag(tags.length - 1);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <JxInputField
        label="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={addTag}
        helperText="Enter добавляет тег, Backspace удаляет последний"
        ariaLabel="Ввод тега"
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-r-sm)' }}>
          {tags.map((tag, index) => (
            <JxChip key={tag} removable onRemove={() => removeTag(index)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

